<!doctype html><html lang="en" data-theme="<?=esc($_COOKIE['atlas_theme']??'light')?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#173b6c"><title>Mobile Tools · Atlas</title><link rel="manifest" href="<?=esc(url_for('manifest.json'))?>"><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="mobile-work-body"><main class="mobile-work"><header><span class="brand-mark">A</span><div><small>MY ATLAS</small><h1>Mobile tools</h1></div><button class="button secondary" data-theme-toggle>Theme</button></header><?php if($notice):?><div class="page-flash success"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><section class="mobile-hero"><small>YOUR SCHEDULE</small><h2><?=count($myShifts)?> upcoming</h2><p>Install Atlas, export your calendar, and acknowledge published assignments.</p><a class="button primary" href="<?=esc(url_for('calendar-export'))?>">Download calendar</a></section><section class="panel" style="padding:18px"><h2>Delivery schedule</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="save_delivery_settings"><label>Quiet hours start<input type="time" name="quiet_starts_at" value="<?=esc(substr((string)$deliverySettings['quiet_starts_at'],0,5))?>"></label><label>Quiet hours end<input type="time" name="quiet_ends_at" value="<?=esc(substr((string)$deliverySettings['quiet_ends_at'],0,5))?>"></label><label>Digest<select name="digest_frequency"><option value="immediate" <?=$deliverySettings['digest_frequency']==='immediate'?'selected':''?>>Immediate</option><option value="daily" <?=$deliverySettings['digest_frequency']==='daily'?'selected':''?>>Daily</option><option value="weekly" <?=$deliverySettings['digest_frequency']==='weekly'?'selected':''?>>Weekly</option></select></label><label class="check-label"><input type="checkbox" name="push_enabled" value="1" <?=!empty($deliverySettings['push_enabled'])?'checked':''?>><span>Push notifications when available</span></label><button class="button primary">Save delivery settings</button></form></section><section class="panel" style="padding:18px;margin-top:14px"><h2>Schedule acknowledgment</h2><?php foreach($myShifts as $shift):?><div class="planning-row"><span><strong><?=esc(date('D, M j',strtotime($shift['shift_date'])))?></strong><small><?=esc(date('g:i A',strtotime($shift['starts_at'])).' · '.$shift['department_name'])?></small></span><?php if(isset($scheduleAcknowledgments[$shift['id']])):?><b class="state-pill covered">Acknowledged</b><?php else:?><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="acknowledge_shift"><input type="hidden" name="shift_id" value="<?=$shift['id']?>"><button class="button primary">Acknowledge</button></form><?php endif;?></div><?php endforeach;?></section><nav class="mobile-tabbar"><a href="<?=esc(url_for('mobile'))?>">Today</a><a href="<?=esc(url_for('my-schedule'))?>">Schedule</a><a href="<?=esc(url_for('notifications'))?>">Alerts</a><a href="<?=esc(url_for('employee'))?>">Profile</a></nav></main><script src="<?=esc(url_for('assets/app.js'))?>"></script></body></html>
